import os,json
results=[]
for name,flags in [('read',os.O_RDONLY),('path',os.O_PATH)]:
    entry={'kind':name}
    try:
        fd=os.open('/',flags|os.O_DIRECTORY|os.O_CLOEXEC|os.O_NOFOLLOW)
        try:
            entry['opened']=True
            os.fchdir(fd)
            entry['fchdir']=os.getcwd()
        finally:
            os.close(fd)
    except OSError as error:
        entry.update(errno=error.errno,error=str(error))
    results.append(entry)
print(json.dumps({'uid':os.getuid(),'results':results}))

